<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {useResearchData} from '../hooks/useResearch';import {getRevisions,getRevisionRun} from '../api/calibrations';import {RevisionSummary} from '../types/calibration';import {Run} from '../types/domain';import RunSummary from '../components/RunSummary.vue';import SpectralPlot from '../components/SpectralPlot.vue';import WeightsTable from '../components/WeightsTable.vue';import DataTable from '../components/common/DataTable.vue';import StatusBadge from '../components/common/StatusBadge.vue';import Notice from '../components/common/Notice.vue';import {number,scientific,time} from '../utils/format';const s=useResearchData(true),route=useRoute(),selected=ref(Number(route.query.run)||0),sampleId=ref(0),revisions=ref<RevisionSummary[]>([]),viewing=ref<number|null>(null),oldRun=ref<Run|null>(null),viewError=ref('');
const run=computed(()=>s.runs.find(r=>r.id===selected.value)||s.runs[0]);
const view=computed<Run|undefined>(()=>viewing.value&&oldRun.value?oldRun.value:run.value);
const sample=computed(()=>view.value?.result.samples?.find(x=>x.sample_id===sampleId.value)||view.value?.result.samples?.[0]);
const kindLabel=(revisions.value.find(r=>r.id===viewing.value)?.kind)==='original'?'原校准依据':'新校准结果';
async function loadRevisions(id:number){viewing.value=null;oldRun.value=null;viewError.value='';revisions.value=id?await getRevisions(id):[]}
watch(()=>run.value?.id,id=>{loadRevisions(id||0)},{immediate:true});
async function showRevision(revision:number){viewing.value=revision;oldRun.value=null;sampleId.value=0;if(!run.value)return;const effective=revisions.value.find(r=>r.is_effective);if(effective&&effective.id===revision)return;try{oldRun.value=await getRevisionRun(run.value.id,revision) as Run}catch(e){viewError.value=(e as Error).message}}
</script><template><div class="page results-page"><div class="page-title"><div><p class="eyebrow">COMPOSITION & RESIDUAL / 04</p><h1>配比与残差<span>一份数值结果，保留它的可辨识性边界与校准版本。</span></h1></div><RouterLink class="outline" :to="'/notes'+(run?'?run='+run.id:'')">记录复配建议 →</RouterLink></div><Notice :message="s.error||viewError" @retry="s.refresh"/><div class="run-picker"><label>解混档案<select aria-label="解混档案" :value="run?.id||''" @change="selected=Number(($event.target as HTMLSelectElement).value);sampleId=0"><option v-for="r in s.runs" :key="r.id" :value="r.id">#{{r.id}} / {{r.name}} / {{r.status}}</option></select></label><StatusBadge v-if="run" :status="run.status"/></div><label v-if="revisions.length>1" class="revision-picker">结果版本<select aria-label="结果版本" :value="viewing??(revisions.find(r=>r.is_effective)?.id??'')" @change="showRevision(Number(($event.target as HTMLSelectElement).value))"><option v-for="r in revisions.slice().reverse()" :key="r.id" :value="r.id">{{r.kind==='original'?'原校准依据':'复测校准结果'}} · v{{r.library_version}} · {{r.is_effective?'现行':'历史'}} · {{time(r.created_at)}}</option></select></label>
<template v-if="view&&view.status==='completed'&&sample"><div v-if="viewing&&oldRun" class="revision-banner">正在查看历史版本（{{kindLabel}} v{{oldRun.current_library_version}}），不改变现行结果。<button class="text-link" @click="showRevision(revisions.find(r=>r.is_effective)!.id)">回到现行结果</button></div><div class="revision-meta"><span>校准版本 <b>v{{view.result.library.calibration_version}}</b></span><span>结果来源 <b>{{view.current_result_kind==='original'?'原校准依据':'复测校准结果'}}</b></span><span>输入SHA256 <b class="mono">{{view.result.input_hash.slice(0,16)}}…</b></span></div><RunSummary :run="view"/><label>当前混合样本<select aria-label="当前混合样本" v-model.number="sampleId"><option :value="0">{{view.result.samples[0].code}} / {{view.result.samples[0].name}}</option><option v-for="x in view.result.samples.slice(1)" :key="x.sample_id" :value="x.sample_id">{{x.code}} / {{x.name}}</option></select></label><SpectralPlot :library="view.result.library" :endmembers="view.result.endmembers" :sample="sample"/><div class="residual-summary"><div><span>RSS</span><b>{{scientific(sample.point_fit.rss)}}</b></div><div><span>RMSE / 反射率</span><b>{{number(sample.point_fit.rmse,5)}}</b></div><div><span>KKT活动误差</span><b>{{scientific(sample.point_fit.active_stationarity_error)}}</b></div><strong :class="sample.high_residual?'warning':'supported'">{{sample.high_residual?'残差高于3σ参考，需查失配':'残差未超3σ参考，仍需复配验证'}}</strong></div><WeightsTable :endmembers="view.result.endmembers" :sample="sample"/><p class="conditional-note">{{sample.interval_note}}</p><div class="section-heading"><h2>波段残差明细</h2><span>观测 − 约束重建</span></div><DataTable :head="['波长 / nm','观测反射率','重建反射率','残差']"><tr v-for="(wave,i) in view.result.library.wavelengths" :key="wave"><td>{{wave}}</td><td>{{number(sample.observed[i],5)}}</td><td>{{number(sample.point_fit.reconstructed[i],5)}}</td><td>{{number(sample.point_fit.residual[i],5)}}</td></tr></DataTable><div class="section-heading"><h2>条件重拟合抽样</h2><span>展示前10次，API保存全部{{sample.repeats}}次</span></div><DataTable :head="['重复',...view.result.endmembers.map(e=>e.name),'RSS']"><tr v-for="(w,j) in sample.replicate_weights.slice(0,10)" :key="j"><td>{{j+1}}</td><td v-for="(v,i) in w" :key="i">{{number(v,5)}}</td><td>{{scientific(sample.replicate_rss[j])}}</td></tr></DataTable><p class="caption">{{view.result.assumptions}}</p><p class="fingerprint">输入SHA256 {{view.result.input_hash}} · 结果版本 {{view.current_result_id??'原'}} · 校准 v{{view.result.library.calibration_version}}</p></template><div v-else-if="run" class="pending"><h2>{{run.status==='failed'?'研究未能完成':'后台正在枚举支持集与条件重拟合'}}</h2><p>{{run.error||'独立worker执行Python计算，本页每2秒更新。'}}</p></div><p v-else class="empty">尚无解混研究，请先选择可辨识光谱库。</p></div></template>
